{
  "name": "LinkedIn Headline A/B Tester",
  "description": "Generate and score multiple LinkedIn headline variations based on your role and goals. Receive optimized options with detailed rationales to enhance your professional profile."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback } from 'react';
import type { HeadlineSuggestion } from './types';
import { generateHeadlines } from './services/geminiService';
import { HeadlineCard } from './components/HeadlineCard';
import { HeroSection } from './components/HeroSection';
import { InputForm } from './components/InputForm';
import { LoadingSpinner } from './components/LoadingSpinner';

const App: React.FC = () => {
  const [role, setRole] = useState('');
  const [goals, setGoals] = useState('');
  const [suggestions, setSuggestions] = useState<HeadlineSuggestion[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = useCallback(async (event: React.FormEvent) => {
    event.preventDefault();
    if (!role.trim() || !goals.trim()) {
      setError('Please fill out both your current role and career goals.');
      return;
    }

    setIsLoading(true);
    setError(null);
    setSuggestions([]);

    try {
      const results = await generateHeadlines(role, goals);
      setSuggestions(results);
    } catch (err) {
      setError(
        'Failed to generate headlines. Please check your connection or API key and try again.'
      );
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [role, goals]);

  const handleClear = useCallback(() => {
    setRole('');
    setGoals('');
    setSuggestions([]);
    setError(null);
    setIsLoading(false);
  }, []);

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800">
      <main className="container mx-auto px-4 py-8 md:py-12">
        <HeroSection />

        <div className="max-w-3xl mx-auto">
          <InputForm 
            role={role} 
            setRole={setRole} 
            goals={goals} 
            setGoals={setGoals}
            isLoading={isLoading} 
            onSubmit={handleSubmit}
            onClear={handleClear}
            hasSuggestions={suggestions.length > 0}
          />

          {error && (
            <div className="mt-6 bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative" role="alert">
              <strong className="font-bold">Error: </strong>
              <span className="block sm:inline">{error}</span>
            </div>
          )}

          <div className="mt-8">
            {isLoading && <LoadingSpinner />}

            {suggestions.length > 0 && (
              <div className="space-y-6">
                 <h2 className="text-2xl md:text-3xl font-bold text-slate-800 text-center mb-6">
                    Generated Headlines
                </h2>
                {suggestions.map((suggestion, index) => (
                  <HeadlineCard key={index} suggestion={suggestion} index={index} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>
      <footer className="text-center py-6 text-slate-500 text-sm">
        <p>Powered by Gemini API</p>
      </footer>
    </div>
  );
};

export default App;

export interface HeadlineSuggestion {
  headline: string;
  score: number;
  rationale: string;
}

import { GoogleGenAI, Type } from '@google/genai';
import type { HeadlineSuggestion } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set.");
}
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const headlineSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      headline: {
        type: Type.STRING,
        description: 'The generated LinkedIn headline.',
      },
      score: {
        type: Type.INTEGER,
        description: 'A score from 1-100 evaluating the headline\'s effectiveness.',
      },
      rationale: {
        type: Type.STRING,
        description: 'A brief explanation for the score, covering clarity, keywords, and audience appeal.',
      },
    },
    required: ['headline', 'score', 'rationale'],
  },
};

export async function generateHeadlines(role: string, goals: string): Promise<HeadlineSuggestion[]> {
  const prompt = `
    As an expert career coach and LinkedIn branding specialist, generate exactly 10 optimized LinkedIn headlines for a professional with the following details:
    - Current Role/Title: "${role}"
    - Career Goals: "${goals}"

    For each headline, provide a score from 1 to 100 and a brief rationale. The score should be based on:
    1.  **Clarity & Conciseness**: Is it easy to understand at a glance?
    2.  **Keyword Optimization**: Does it include relevant keywords for their industry and target roles?
    3.  **Audience Appeal**: Is it compelling to their target audience (e.g., recruiters, clients, industry leaders)?

    The final output must be a JSON array of objects, strictly following the provided schema. Do not include any other text or explanations outside of the JSON structure.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: headlineSchema,
        temperature: 0.7,
      },
    });

    const jsonText = response.text.trim();
    const suggestions: HeadlineSuggestion[] = JSON.parse(jsonText);

    // Sort by score descending
    suggestions.sort((a, b) => b.score - a.score);

    return suggestions;
  } catch (error) {
    console.error('Error calling Gemini API:', error);
    throw new Error('The request to the AI service failed. Please try again.');
  }
}

import React from 'react';
import type { HeadlineSuggestion } from '../types';

interface ScoreCircleProps {
  score: number;
}

const ScoreCircle: React.FC<ScoreCircleProps> = ({ score }) => {
  const getScoreColor = (s: number) => {
    if (s >= 90) return 'text-emerald-500';
    if (s >= 75) return 'text-sky-500';
    if (s >= 60) return 'text-yellow-500';
    return 'text-rose-500';
  };

  const colorClass = getScoreColor(score);
  const circumference = 2 * Math.PI * 45; // 45 is the radius
  const strokeDashoffset = circumference - (score / 100) * circumference;

  return (
    <div className="relative w-24 h-24 flex-shrink-0">
      <svg className="w-full h-full" viewBox="0 0 100 100">
        <circle
          className="text-slate-200"
          strokeWidth="10"
          stroke="currentColor"
          fill="transparent"
          r="45"
          cx="50"
          cy="50"
        />
        <circle
          className={`${colorClass} transition-all duration-1000 ease-in-out`}
          strokeWidth="10"
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          stroke="currentColor"
          fill="transparent"
          r="45"
          cx="50"
          cy="50"
          transform="rotate(-90 50 50)"
        />
      </svg>
      <span className={`absolute inset-0 flex items-center justify-center text-2xl font-bold ${colorClass}`}>
        {score}
      </span>
    </div>
  );
};


interface HeadlineCardProps {
  suggestion: HeadlineSuggestion;
  index: number;
}

export const HeadlineCard: React.FC<HeadlineCardProps> = ({ suggestion, index }) => {
    const { headline, score, rationale } = suggestion;

    return (
        <div className="bg-white rounded-xl shadow-md overflow-hidden transform hover:scale-105 transition-transform duration-300 ease-in-out border border-slate-100">
            <div className="p-6 md:p-8 flex flex-col md:flex-row items-start md:items-center gap-6">
                <ScoreCircle score={score} />
                <div className="flex-1">
                    <p className="text-indigo-600 font-semibold text-sm mb-2">Option {index + 1}</p>
                    <h3 className="text-xl font-bold text-slate-900 mb-3">{headline}</h3>
                    <p className="text-slate-600 leading-relaxed">{rationale}</p>
                </div>
            </div>
        </div>
    );
};

